UPDATE lessons SET content = $lsn${"steps": [{"step_type": "concept", "title": "Say what you don't do", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "안 means not. It goes right before the verb.", "example": {"sentence": "저는 커피를 안 마셔요.", "translation": "I don't drink coffee.", "tts": true, "words": [{"parts": [{"text": "저는", "meaning": "I (topic)", "highlight": false}]}, {"parts": [{"text": "커피", "meaning": "coffee", "highlight": false}, {"text": "를", "meaning": "object", "highlight": false}]}, {"parts": [{"text": "안", "meaning": "not", "highlight": true}]}, {"parts": [{"text": "마셔요", "meaning": "drink", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "안 is its own word", "instruction": "", "content": {"character": "turtle", "mood": "happy", "explanation": "안 is a whole word, not a block. It stands alone, so you can't split it.", "example": {"sentence": "안 먹어요.", "translation": "don't eat", "tts": true, "words": [{"parts": [{"text": "안", "meaning": "not", "highlight": true}]}, {"parts": [{"text": "먹", "meaning": "eat", "highlight": false}, {"text": "어요", "meaning": "polite ending", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "I don't eat bread.", "sentence": "저는 빵을 [ ? ].", "options": ["먹어요 안", "안 먹어요"], "answer": "안 먹어요", "feedback": {"correct": "Yes! 안 goes right before the verb.", "incorrect": "안 comes before the verb, not after it."}}]}}, {"step_type": "concept", "title": "New word: 읽어요", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "읽어요 means read. Other words come first, then 안, then the verb.", "example": {"sentence": "민수는 책을 안 읽어요.", "translation": "Minsu doesn't read books.", "tts": true, "words": [{"parts": [{"text": "민수는", "meaning": "Minsu (topic)", "highlight": false}]}, {"parts": [{"text": "책", "meaning": "book", "highlight": false}, {"text": "을", "meaning": "object", "highlight": false}]}, {"parts": [{"text": "안", "meaning": "not", "highlight": true}]}, {"parts": [{"text": "읽어요", "meaning": "read", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "Places work too", "instruction": "", "content": {"character": "turtle", "mood": "happy", "explanation": "It works with 가요 too. The place comes first, then 안, then 가요.", "example": {"sentence": "유미는 학교에 안 가요.", "translation": "Yumi doesn't go to school.", "tts": true, "words": [{"parts": [{"text": "유미는", "meaning": "Yumi (topic)", "highlight": false}]}, {"parts": [{"text": "학교", "meaning": "school", "highlight": false}, {"text": "에", "meaning": "place", "highlight": false}]}, {"parts": [{"text": "안", "meaning": "not", "highlight": true}]}, {"parts": [{"text": "가요", "meaning": "go", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "Minsu doesn't go to school.", "sentence": "민수는 [ ? ].", "options": ["학교에 안 가요", "안 학교에 가요"], "answer": "학교에 안 가요", "feedback": {"correct": "Right! 안 sits right before 가요.", "incorrect": "안 doesn't go before the place. Put it right before 가요."}}]}}, {"step_type": "concept", "title": "No shape to choose", "instruction": "", "content": {"character": "turtle", "mood": "thinking", "explanation": "안 never changes shape. It is the same after a consonant or a vowel.", "example": {"sentence": "저는 물을 안 마셔요.", "translation": "I don't drink water.", "tts": true, "words": [{"parts": [{"text": "저는", "meaning": "I (topic)", "highlight": false}]}, {"parts": [{"text": "물", "meaning": "water", "highlight": false}, {"text": "을", "meaning": "object", "highlight": false}]}, {"parts": [{"text": "안", "meaning": "not", "highlight": true}]}, {"parts": [{"text": "마셔요", "meaning": "drink", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "Other blocks stay", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "안 doesn't change other blocks. 빵 still takes 을, and 커피 still takes 를.", "example": {"sentence": "민수는 빵을 안 먹어요.", "translation": "Minsu doesn't eat bread.", "tts": true, "words": [{"parts": [{"text": "민수는", "meaning": "Minsu (topic)", "highlight": false}]}, {"parts": [{"text": "빵", "meaning": "bread", "highlight": false}, {"text": "을", "meaning": "object", "highlight": true}]}, {"parts": [{"text": "안", "meaning": "not", "highlight": true}]}, {"parts": [{"text": "먹어요", "meaning": "eat", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "I don't drink coffee.", "sentence": "저는 커피 [ ? ] 안 마셔요.", "options": ["을", "를"], "answer": "를", "feedback": {"correct": "Great! 커피 ends in a vowel, so it still takes 를.", "incorrect": "커피 ends in a vowel. After a vowel, use 를."}}]}}, {"step_type": "concept", "title": "How you'll practice", "instruction": "", "content": {"character": "turtle", "mood": "thinking", "explanation": "안 stays whole, so there's nothing to split. In Sentence Building, you place 안 and split 을/를.", "example": null, "tap_to_assemble": false}}, {"step_type": "completion", "title": "안 Learned!", "instruction": "Next, practice it with the rabbit.", "content": {"text": "안 means not. It goes right before the verb.\n커피를 안 마셔요. 학교에 안 가요.", "highlights": ["안"]}}]}$lsn$::jsonb
WHERE lesson_id = 'u2-l3-learn';
UPDATE lessons SET content = $lsn${"steps": [{"step_type": "concept", "title": "Quick recap", "instruction": "", "content": {"character": "rabbit", "mood": "happy", "explanation": "안 means not. It goes right before the verb.", "example": {"sentence": "저는 커피를 안 마셔요.", "translation": "I don't drink coffee.", "tts": true, "words": [{"parts": [{"text": "저는", "meaning": "I (topic)", "highlight": false}]}, {"parts": [{"text": "커피", "meaning": "coffee", "highlight": false}, {"text": "를", "meaning": "object", "highlight": false}]}, {"parts": [{"text": "안", "meaning": "not", "highlight": true}]}, {"parts": [{"text": "마셔요", "meaning": "drink", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "intro", "title": "Vocabulary: Verbs", "instruction": "Tap and listen. You'll use all of these today.", "content": {"explanation": {"title": "Words for today"}, "sentences": [{"korean": "안", "english": "Not", "tts": true, "chunks": [{"display": "안", "tokens": [{"text": "안", "meaning": "not"}]}]}, {"korean": "마셔요", "english": "Drink", "tts": true, "chunks": [{"display": "마셔요", "tokens": [{"text": "마셔요", "meaning": "drink"}]}]}, {"korean": "먹어요", "english": "Eat", "tts": true, "chunks": [{"display": "먹어요", "tokens": [{"text": "먹어요", "meaning": "eat"}]}]}, {"korean": "가요", "english": "Go", "tts": true, "chunks": [{"display": "가요", "tokens": [{"text": "가요", "meaning": "go"}]}]}, {"korean": "읽어요", "english": "Read", "tts": true, "chunks": [{"display": "읽어요", "tokens": [{"text": "읽어요", "meaning": "read"}]}]}, {"korean": "좋아해요", "english": "Like", "tts": true, "chunks": [{"display": "좋아해요", "tokens": [{"text": "좋아해요", "meaning": "like"}]}]}, {"korean": "네", "english": "Yes", "tts": true, "chunks": [{"display": "네", "tokens": [{"text": "네", "meaning": "yes"}]}]}, {"korean": "아니요", "english": "No", "tts": true, "chunks": [{"display": "아니요", "tokens": [{"text": "아니요", "meaning": "no"}]}]}]}}, {"step_type": "practice", "title": "Round 1: Where does 안 go?", "instruction": "안 goes right before the verb.", "content": {"exercises": [{"type": "fill_blank", "instruction": "I don't eat bread.", "sentence": "저는 빵을 [ ? ].", "options": ["안 먹어요", "먹어요 안"], "answer": "안 먹어요", "feedback": {"correct": "Correct! 안 goes right before 먹어요."}}, {"type": "fill_blank", "instruction": "Yumi doesn't go to school.", "sentence": "유미는 학교에 [ ? ].", "options": ["가요 안", "안 가요"], "answer": "안 가요", "feedback": {"correct": "Right! 안 goes right before 가요."}}, {"type": "fill_blank", "instruction": "I don't drink water.", "sentence": "저는 물을 [ ? ].", "options": ["안 마셔요", "마셔요 안"], "answer": "안 마셔요", "feedback": {"correct": "Great! 안 goes right before 마셔요."}}, {"type": "fill_blank", "instruction": "Minsu doesn't read books.", "sentence": "민수는 책을 [ ? ].", "options": ["읽어요 안", "안 읽어요"], "answer": "안 읽어요", "feedback": {"correct": "Perfect! 안 goes right before 읽어요."}}, {"type": "fill_blank", "instruction": "I don't like coffee.", "sentence": "저는 커피를 [ ? ].", "options": ["좋아해요 안", "안 좋아해요"], "answer": "안 좋아해요", "feedback": {"correct": "Correct! 안 goes right before 좋아해요."}}]}}, {"step_type": "practice", "title": "Round 2: 을 or 를?", "instruction": "안 changes nothing here. Look at the last sound of the word.", "content": {"exercises": [{"type": "fill_blank", "instruction": "I don't drink coffee.", "sentence": "저는 커피 [ ? ] 안 마셔요.", "options": ["을", "를"], "answer": "를", "feedback": {"correct": "Correct! 커피 ends in a vowel, so it takes 를."}}, {"type": "fill_blank", "instruction": "Minsu doesn't eat bread.", "sentence": "민수는 빵 [ ? ] 안 먹어요.", "options": ["를", "을"], "answer": "을", "feedback": {"correct": "Right! 빵 ends in a consonant, so it takes 을."}}, {"type": "fill_blank", "instruction": "Yumi doesn't read books.", "sentence": "유미는 책 [ ? ] 안 읽어요.", "options": ["를", "을"], "answer": "을", "feedback": {"correct": "Great! 책 ends in a consonant, so it takes 을."}}, {"type": "fill_blank", "instruction": "I don't eat apples.", "sentence": "저는 사과 [ ? ] 안 먹어요.", "options": ["을", "를"], "answer": "를", "feedback": {"correct": "Perfect! 사과 ends in a vowel, so it takes 를."}}, {"type": "fill_blank", "instruction": "Minsu doesn't drink water.", "sentence": "민수는 물 [ ? ] 안 마셔요.", "options": ["을", "를"], "answer": "을", "feedback": {"correct": "Correct! 물 ends in a consonant, so it takes 을."}}, {"type": "fill_blank", "instruction": "Yumi doesn't drink milk.", "sentence": "유미는 우유 [ ? ] 안 마셔요.", "options": ["을", "를"], "answer": "를", "feedback": {"correct": "Right! 우유 ends in a vowel, so it takes 를."}}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #1", "instruction": "Build the sentence: \"I don't drink coffee.\" 안 stays whole. Split 을/를. 커피 ends in a vowel, so use 를.", "contentObj": {"sentence": "저는 커피를 안 마셔요.", "translation": "I don't drink coffee.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["저는"], "correct_turtle": ["저는"], "turtle_explanation": "Keep '저는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["커피를"], "correct_turtle": ["커피", "를"], "turtle_explanation": "'를' marks the object. After a vowel use 를, after a consonant use 을."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["안"], "correct_turtle": ["안"], "turtle_explanation": "'안' means 'not'. It goes right before the verb."}, {"id": "e4", "isTarget": true, "correct_rabbit": ["마셔요"], "correct_turtle": ["마셔요"], "turtle_explanation": "Keep '마셔요' as one block — it is not this lesson's focus."}], "options": [{"id": "o1", "text": "을", "mode": "turtle"}, {"id": "o2", "text": "커피을", "mode": "rabbit"}, {"id": "o3", "text": "마셔요", "mode": "rabbit"}, {"id": "o4", "text": "저는", "mode": "rabbit"}, {"id": "o5", "text": "마셔요", "mode": "turtle"}, {"id": "o6", "text": "저는", "mode": "turtle"}, {"id": "o7", "text": "커피", "mode": "turtle"}, {"id": "o8", "text": "안", "mode": "rabbit"}, {"id": "o9", "text": "커피를", "mode": "rabbit"}, {"id": "o10", "text": "를", "mode": "turtle"}, {"id": "o11", "text": "안", "mode": "turtle"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #2", "instruction": "Build the sentence: \"Minsu doesn't eat bread.\" 안 stays whole. Split 을/를.", "contentObj": {"sentence": "민수는 빵을 안 먹어요.", "translation": "Minsu doesn't eat bread.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["민수는"], "correct_turtle": ["민수는"], "turtle_explanation": "Keep '민수는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["빵을"], "correct_turtle": ["빵", "을"], "turtle_explanation": "'을' marks the object. After a vowel use 를, after a consonant use 을."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["안"], "correct_turtle": ["안"], "turtle_explanation": "'안' means 'not'. It goes right before the verb."}, {"id": "e4", "isTarget": true, "correct_rabbit": ["먹어요"], "correct_turtle": ["먹어요"], "turtle_explanation": "Keep '먹어요' as one block — it is not this lesson's focus."}], "options": [{"id": "o1", "text": "을", "mode": "turtle"}, {"id": "o2", "text": "빵", "mode": "turtle"}, {"id": "o3", "text": "먹어요", "mode": "rabbit"}, {"id": "o4", "text": "안", "mode": "rabbit"}, {"id": "o5", "text": "빵를", "mode": "rabbit"}, {"id": "o6", "text": "민수는", "mode": "rabbit"}, {"id": "o7", "text": "먹어요", "mode": "turtle"}, {"id": "o8", "text": "민수는", "mode": "turtle"}, {"id": "o9", "text": "빵을", "mode": "rabbit"}, {"id": "o10", "text": "를", "mode": "turtle"}, {"id": "o11", "text": "안", "mode": "turtle"}]}}, {"step_type": "intro", "title": "Conversation", "instruction": "Take a break and listen. You know these words now.", "content": {"explanation": {"title": "Do you drink coffee?"}, "sentences": [{"korean": "민수: 유미 씨, 커피를 마셔요?", "english": "Minsu: Yumi, do you drink coffee?", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "유미", "tokens": [{"text": "유미", "meaning": "Yumi (name)"}]}, {"display": "씨,", "tokens": [{"text": "씨", "meaning": "Mr./Ms."}]}, {"display": "커피를", "tokens": [{"text": "커피", "